import React, { useState, useEffect } from 'react';
// Assuming your data structure now uses imageUrl instead of emoji
import { C, slides } from '../data';

export default function Hero() {
  const [current, setCurrent] = useState(0);

  useEffect(() => {
    const t = setInterval(() => setCurrent((c) => (c + 1) % slides.length), 5000);
    return () => clearInterval(t);
  }, []);

  const prev = () => setCurrent((c) => (c - 1 + slides.length) % slides.length);
  const next = () => setCurrent((c) => (c + 1) % slides.length);
  const slide = slides[current];

  return (
    <section id="hero" style={{ background: slide.bg, transition: 'background 1s ease', minHeight: '100vh', display: 'flex', alignItems: 'center', position: 'relative', overflow: 'hidden' }}>
      {/* Decorative circles */}
      <div style={{ position: 'absolute', top: -80, right: -80, width: 380, height: 380, borderRadius: '50%', background: C.gold, opacity: 0.08, zIndex: 0 }} />
      <div style={{ position: 'absolute', bottom: -60, left: -60, width: 280, height: 280, borderRadius: '50%', background: C.goldLight, opacity: 0.08, zIndex: 0 }} />
      {/* Grid */}
      <div style={{ position: 'absolute', inset: 0, opacity: 0.04, backgroundImage: `linear-gradient(${C.goldLight} 1px, transparent 1px), linear-gradient(90deg, ${C.goldLight} 1px, transparent 1px)`, backgroundSize: '60px 60px', zIndex: 0 }} />

      <div style={{ maxWidth: 1280, margin: '0 auto', padding: '112px 24px 64px', width: '100%', position: 'relative', zIndex: 1 }}>
        <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 48 }}>
          {/* Text Section */}
          <div style={{ flex: 1, minWidth: 300 }}>
            <div style={{ display: 'inline-block', padding: '6px 16px', borderRadius: 99, fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.15em', marginBottom: 24, background: 'rgba(245,166,35,0.25)', color: C.goldLight }}>
              {slide.tag}
            </div>
            <h1 style={{ fontSize: 'clamp(2rem, 5vw, 3.5rem)', fontWeight: 800, color: C.white, fontFamily: "'Playfair Display', Georgia, serif", lineHeight: 1.2, whiteSpace: 'pre-line', marginBottom: 24, textShadow: '0 2px 20px rgba(0,0,0,0.15)' }}>
              {slide.title}
            </h1>
            <p style={{ fontSize: 18, color: 'rgba(219,234,254,0.9)', marginBottom: 40, lineHeight: 1.7, maxWidth: 500 }}>
              {slide.subtitle}
            </p>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 16 }}>
              <button
                onClick={() => document.getElementById('contact')?.scrollIntoView({ behavior: 'smooth' })}
                style={{ padding: '14px 32px', borderRadius: 16, fontWeight: 700, fontSize: 14, background: C.gold, color: C.blue, border: 'none', cursor: 'pointer', boxShadow: '0 8px 24px rgba(245,166,35,0.4)', transition: 'transform 0.2s' }}
                onMouseEnter={e => e.currentTarget.style.transform = 'scale(1.05)'}
                onMouseLeave={e => e.currentTarget.style.transform = 'scale(1)'}
              >
                Join as Tutor
              </button>
              <button
                onClick={() => document.getElementById('contact')?.scrollIntoView({ behavior: 'smooth' })}
                style={{ padding: '14px 32px', borderRadius: 16, fontWeight: 700, fontSize: 14, background: 'rgba(255,255,255,0.12)', color: C.white, border: '2px solid rgba(255,255,255,0.5)', cursor: 'pointer', backdropFilter: 'blur(8px)', transition: 'all 0.2s' }}
                onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.25)'; }}
                onMouseLeave={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.12)'; }}
              >
                Find a Tutor →
              </button>
            </div>
          </div>

          {/* Image Card Section - Updated for Realistic Images */}
          <div style={{ flex: 1, minWidth: 260, display: 'flex', justifyContent: 'center' }}>
            <div style={{ 
              width: 320, // Slightly wider for photos
              height: 380, // Slightly taller
              borderRadius: 28, 
              overflow: 'hidden', // Required to crop the image to the border radius
              background: 'rgba(255,255,255,0.12)', 
              border: '1px solid rgba(255,255,255,0.2)', 
              backdropFilter: 'blur(20px)', 
              boxShadow: '0 20px 60px rgba(0,0,0,0.3)', // Increased shadow depth
              position: 'relative', 
              animation: 'float 6s ease-in-out infinite' // Slowed down the float
            }}>
              {/* The Real Image */}
              <img 
                src={slide.imageUrl} 
                alt={slide.tag} 
                style={{ 
                  width: '100%', 
                  height: '100%', 
                  objectFit: 'cover', // Ensures the image fills the space without distortion
                  display: 'block' 
                }} 
              />

              {/* Gradient Overlay on image for better badge contrast */}
              <div style={{ position: 'absolute', inset: 0, background: 'linear-gradient(to bottom, transparent 60%, rgba(0,0,0,0.5))' }} />

              {/* Badges - Kept these as they add a nice UI layer over the photo */}
              <div style={{ position: 'absolute', top: 16, right: 16, background: C.white, borderRadius: 12, padding: '6px 12px', boxShadow: '0 4px 12px rgba(0,0,0,0.15)', display: 'flex', alignItems: 'center', gap: 6, zIndex: 2 }}>
                <span style={{ color: C.gold, fontSize: 14 }}>⭐</span>
                <span style={{ fontSize: 11, fontWeight: 700, color: C.blue, textTransform: 'uppercase' }}>Verified</span>
              </div>
              <div style={{ position: 'absolute', bottom: 16, left: 16, background: 'rgba(255,255,255,0.9)', borderRadius: 12, padding: '6px 12px', boxShadow: '0 4px 12px rgba(0,0,0,0.15)', display: 'flex', alignItems: 'center', gap: 6, zIndex: 2, backdropFilter: 'blur(4px)' }}>
                <span style={{ fontSize: 16 }}>👨‍🎓</span>
                <span style={{ fontSize: 11, fontWeight: 700, color: C.blue, textTransform: 'uppercase' }}>500+ Tutors</span>
              </div>
            </div>
          </div>
        </div>

        {/* Slider Controls */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 16, marginTop: 64 }}>
          <button onClick={prev} style={{ width: 44, height: 44, borderRadius: '50%', background: 'rgba(255,255,255,0.1)', border: '1px solid rgba(255,255,255,0.2)', color: C.white, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 20, transition: 'background 0.2s' }} onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.2)'} onMouseLeave={e => e.currentTarget.style.background = 'rgba(255,255,255,0.1)'}>‹</button>
          {slides.map((_, i) => (
            <button key={i} onClick={() => setCurrent(i)} style={{ width: i === current ? 32 : 10, height: 10, borderRadius: 99, background: i === current ? C.gold : 'rgba(255,255,255,0.3)', border: 'none', cursor: 'pointer', transition: 'all 0.3s ease' }} />
          ))}
          <button onClick={next} style={{ width: 44, height: 44, borderRadius: '50%', background: 'rgba(255,255,255,0.1)', border: '1px solid rgba(255,255,255,0.2)', color: C.white, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 20, transition: 'background 0.2s' }} onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.2)'} onMouseLeave={e => e.currentTarget.style.background = 'rgba(255,255,255,0.1)'}>›</button>
        </div>
      </div>

      {/* Ensure you have the float animation defined in your global CSS */}
      <style>{`
        @keyframes float {
          0%, 100% { transform: translateY(0px); }
          50% { transform: translateY(-15px); }
        }
      `}</style>
    </section>
  );
}
